class PerspectiveFloor:
    """Space Harrier-style ground plane. The camera only flies forward, so the
    per-pixel lookup is built once; each frame just shifts the texture rows."""

    def __init__(self, texture, size, horizon, cam_height=40.0, focal=200.0):
        self.tex = pygame.surfarray.array3d(texture)        # (tex_w, tex_h, 3), must tile
        tw, self.th = self.tex.shape[:2]
        w, h = size
        rows = np.arange(max(horizon + 1, 0), h)             # screen rows that show ground
        self.top = int(rows[0])
        self.depth = cam_height * focal / (rows - horizon)    # world distance of each row
        xs = np.arange(w) - w / 2
        self.u = (xs[:, None] * self.depth[None, :] / focal).astype(np.int64) % tw
        self.surface = pygame.Surface((w, h - self.top))

    def draw(self, screen, distance):
        v = (self.depth + distance).astype(np.int64) % self.th
        pygame.surfarray.blit_array(self.surface, self.tex[self.u, v[None, :]])
        screen.blit(self.surface, (0, self.top))